content.solution_code:
class Attack {
  constructor(name, baseDamage) {
    this.name = name;
    this.baseDamage = baseDamage;
  }

  calculateDamage() {
    return this.baseDamage;
  }
}

class MeleeAttack extends Attack {
  constructor(name, baseDamage, strength) {
    super(name, baseDamage);
    this.strength = strength;
  }

  calculateDamage() {
    return super.calculateDamage() + this.strength;
  }
}

class MagicAttack extends Attack {
  constructor(name, baseDamage, intelligence) {
    super(name, baseDamage);
    this.intelligence = intelligence;
  }

  calculateDamage() {
    return super.calculateDamage() + this.intelligence * 2;
  }
}

// Test cases
const punch = new MeleeAttack("Punch", 10, 5);
const fireball = new MagicAttack("Fireball", 15, 7);

console.log(`${punch.name} deals: ${punch.calculateDamage()} damage.`);
console.log(`${fireball.name} deals: ${fireball.calculateDamage()} damage.`);

